// Package naming is the pure display-name composer (browse-scale D1, moved
// verbatim from internal/api/display.go): the server-side composer behind
// every served display_name, consumed by the api DTO seam that stamps
// title_override. Composition is read-time and never persisted; the
// precedence chains are byte-for-byte the SPA's (Home.tsx seriesDisplayTitle
// and continueTitle's compose branch) so the migration is display-identical.
//
// Cyrillic — and any non-ASCII text — passes through the whole chain
// VERBATIM: no normalization, no transliteration, no reformatting anywhere in
// this package; document strings are compared and emitted as the exact bytes
// the parsers wrote. A name that cannot resolve from facts floors honestly
// ("" at the bottom) — the composer never fabricates one.
//
// Dependency direction: api → naming → store; nothing imports api, and the
// composer imports no enrich symbol — its source bindings arrive ALREADY
// gate-resolved upstream (cmd-side via enrich.ResolveGates).
package naming

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"

	"github.com/mellifera/mellifera/internal/store"
)

// Namer is the per-request composition state for one library: the naming
// options off the library row and the library-wide series map keyed by
// RelativePath. Tombstoned (status "deleted") rows land in the map like any
// other — the SPA's matchSeries skips them at join time, and so does ItemName;
// the map itself stays the raw whole-library read (one QuerySeries, D-9).
// The api-side namerFor builds it (the app method over a.deps); the fields
// are exported so the DTO seam can construct and copy the value directly —
// the struct is type surface, not package surface.
type Namer struct {
	GroupStyle   string                  // "" | "clean" | "raw" (library option; "" = module default = clean)
	ElementTmpl  string                  // the ACTIVE template: the library option, else the module default (elementTemplate); "" = no composition
	SeriesByPath map[string]store.Series // library-wide, RelativePath-keyed (tombstones included, skipped at join)
	// SeriesOverride is the row-under-composition's resolved series' stored
	// title override, point-read beside the row's own by the DTO seam
	// (withSeriesOverride; display-naming D-9 prices these per-series reads).
	// The composed {title} tier is the SPA's seriesDisplayTitle, whose FIRST
	// tier is the series override — so a series rename must reach composed
	// episode names. "" (e.g. plain unit-test namers) floors to the chain, and
	// the item's own override still beats the composed name in ItemName.
	SeriesOverride string
	// TitleSources and LangPrefs are the module's title-walk inputs
	// (plugin-title-enrichment D5): the config-ordered source bindings —
	// ALREADY gate-resolved upstream (cmd-side via enrich.ResolveGates; the
	// composer is pure and never imports enrich) — and the language pick
	// order over object titles. Empty/absent inputs mean the walk is
	// skipped: SeriesName and ItemName stay byte-identical to the pre-walk
	// chains.
	TitleSources []TitleSourceBinding
	LangPrefs    []string
	// Chain is the module's gate-resolved metadata-source chain (media-data-
	// convention D5/D6): the SourceChain list off the SAME ModulePresentation
	// read the title walk's inputs ride in from — the served resolution order
	// the convention projection (metadataFor) walks. Empty/absent means no
	// metadata block is composed: the DTOs stay byte-identical to the
	// pre-projection wire. MetadataFor is the projection that walks it.
	Chain []TitleSourceBinding
	// Mutes is the calling Viewer's ChainMutes (l6-accounts 10.4, threaded
	// in as an explicit namerFor parameter — never a fresh context read in
	// the walk): a source muted for THIS viewer is skipped by the title
	// walk exactly like a gate-disabled entry, so names resolve from the
	// first UNMUTED source per viewer. The floor is per-response only —
	// stored overrides, module configs, and other viewers' responses stay
	// byte-identical. Nil (the zero value, and every mute-blind caller) is
	// the empty-mute floor: byte-identical naming, the pre-accounts shape.
	Mutes map[string]bool
	// ModuleID is the library row's bound module id, read beside the naming
	// options by the SAME GetLibrary namerFor already runs (recommendation-
	// sorting: the photo carve-out branches on it — one comparison, no new
	// store read). "" (the empty namer's missing-library floor, or a plain
	// unit-test literal) is scored like any non-photo library.
	ModuleID string
}

// SeriesName is a series row's display title, precedence-ordered —
// byte-for-byte Home.tsx seriesDisplayTitle: the stored manual override
// first (the operator's name beats every document fact), then the
// config-driven title walk over the plugin namespaces (plugin-title-
// enrichment, above the parser leg), then the cleaned display title
// serial-parser writes into its source namespace, then the raw directory
// name (parsed.dir_name_raw verbatim), else the relative path's last
// segment. GroupStyle "raw" switches to override > dir_name_raw > last
// segment — the walk and the parser title both skipped ("clean" is the
// default; "" is the module default, i.e. clean).
func (n Namer) SeriesName(sr store.Series, override string) string {
	if override != "" {
		return override
	}
	doc := DocMap(sr.Document)
	if n.GroupStyle != "raw" {
		if title := n.SourceTitle(doc); title != "" {
			return title
		}
		if title := sourceStr(doc, "serial-parser", "title"); title != "" {
			return title
		}
	}
	if parsed, ok := doc["parsed"].(map[string]any); ok {
		if raw := strField(parsed, "dir_name_raw"); raw != "" {
			return raw
		}
	}
	return lastSegment(sr.RelativePath)
}

// SourceTitle walks the config-ordered title sources across the document's
// sources.* namespaces (plugin-title-enrichment) — the walk leg of both
// SeriesName and ItemName. Bindings arrive already gate-resolved upstream;
// disabled and viewer-muted entries (the namer's Mutes, l6-accounts 10.4 — a
// per-response floor, storage untouched) are skipped exactly alike. Any
// empty or mistyped title floors to the NEXT source; "" when nothing
// resolves (the caller floors to its next leg). The legs below the walk
// (the serial-parser title, _view.title) are mute-blind on purpose — they
// are not sources.
func (n Namer) SourceTitle(doc map[string]any) string {
	if len(n.TitleSources) == 0 {
		return ""
	}
	sources, _ := doc["sources"].(map[string]any)
	for _, ts := range n.TitleSources {
		if !ts.Enabled || n.Mutes[ts.ID] {
			continue
		}
		ns, ok := sources[ts.ID].(map[string]any)
		if !ok {
			continue
		}
		switch title := ns["title"].(type) {
		case string:
			if title != "" {
				return title
			}
		case map[string]any:
			if picked := pickLanguage(title, n.LangPrefs); picked != "" {
				return picked
			}
		}
	}
	return ""
}

// pickLanguage resolves one object-shaped source title against the module's
// language_preference order (plugin-title-enrichment) — the ONE home of the
// language-pick policy: pref "ru" reads the `russian` key, pref "en" reads
// the `romaji` key, an unknown pref code floors to the next pref, and no
// usable pick floors to "" (the caller moves on to the next source).
func pickLanguage(ns map[string]any, prefs []string) string {
	for _, pref := range prefs {
		var key string
		switch pref {
		case "ru":
			key = "russian"
		case "en":
			key = "romaji"
		default:
			continue
		}
		if s := strField(ns, key); s != "" {
			return s
		}
	}
	return ""
}

// lastSegment is the raw last path segment, verbatim (the SPA's fileName).
func lastSegment(relPath string) string {
	if i := strings.LastIndexByte(relPath, '/'); i >= 0 {
		return relPath[i+1:]
	}
	return relPath
}

// ---- dynamic document accessors ---------------------------------------------
// The documents are the §3.1 dynamic-JSON shape — the store never parses them
// (INV3), so the composer reads them tolerantly, mirroring the SPA's
// stringField/numberField: a wrongly-typed or missing field FLOORS (absent),
// it never errors the read.

// DocMap parses a row document into a generic map — nil on any decode failure
// (a corrupt document floors through the chains, never errors). Numbers decode
// as json.Number so the _view floor's number passthrough stays byte-lossless.
func DocMap(raw json.RawMessage) map[string]any {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var doc map[string]any
	if err := dec.Decode(&doc); err != nil {
		return nil
	}
	return doc
}

// strField reads one field of a dynamic namespace the way the SPA's
// stringField does: a non-empty string, else "" (absent, non-string, and
// empty all floor identically).
func strField(m map[string]any, key string) string {
	if m == nil {
		return ""
	}
	s, _ := m[key].(string)
	return s
}

// sourceStr reads one field of one sources.* namespace: "" when the document
// carries no such namespace or object shape.
func sourceStr(doc map[string]any, namespace, key string) string {
	sources, ok := doc["sources"].(map[string]any)
	if !ok {
		return ""
	}
	ns, ok := sources[namespace].(map[string]any)
	if !ok {
		return ""
	}
	return strField(ns, key)
}

// ---- element template composer (pure) ---------------------------------------

// elementTokens carries the three template values. A nil Season or Episode is
// an ABSENT token — it renders as the empty string, never a placeholder and
// never the raw token. Title is the resolved series display name; an absent
// series title renders empty exactly like an absent number token.
type elementTokens struct {
	Title   string
	Season  *int64
	Episode *int64
}

// composeItemName renders the element template against the episode facts
// (display-naming D-6 — impoverished by design): the only tokens are {title},
// {season}, {episode}; everything else is free text copied through
// byte-for-byte (Cyrillic included, verbatim). Season and episode zero-pad to
// two digits (JS padStart(2, "0") semantics — %02d; a 3+ digit episode
// renders in full). No separator grammar, no conditionals, no format
// specifiers; {episode_end} is deferred. One pass over the template: injected
// values are never re-scanned for tokens, so a title containing "{episode}"
// cannot be re-substituted.
func composeItemName(tmpl string, t elementTokens) string {
	var b strings.Builder
	for i := 0; i < len(tmpl); {
		switch {
		case strings.HasPrefix(tmpl[i:], "{title}"):
			b.WriteString(t.Title)
			i += len("{title}")
		case strings.HasPrefix(tmpl[i:], "{season}"):
			b.WriteString(pad2(t.Season))
			i += len("{season}")
		case strings.HasPrefix(tmpl[i:], "{episode}"):
			b.WriteString(pad2(t.Episode))
			i += len("{episode}")
		default:
			b.WriteByte(tmpl[i])
			i++
		}
	}
	return b.String()
}

// ValidElementTemplate is the PATCH validator's grammar for
// naming_element_name (display-naming 3.2): every {...} group must be
// exactly {title}, {season}, or {episode}. An unclosed '{' is free text —
// the composer copies it through byte-for-byte — never a group; "{}" and any
// other group content are 400.
func ValidElementTemplate(tmpl string) bool {
	for i := 0; i < len(tmpl); {
		if tmpl[i] != '{' {
			i++
			continue
		}
		end := strings.IndexByte(tmpl[i:], '}')
		if end < 0 {
			return true // unterminated brace: free text, not a group
		}
		switch tmpl[i+1 : i+end] {
		case "title", "season", "episode":
			i += end + 1
		default:
			return false
		}
	}
	return true
}

// pad2 renders one number token: zero-padded to two digits when shorter
// (JS String(v).padStart(2, "0") — %02d), a 3+ digit value in full, an
// absent token as the empty string.
func pad2(v *int64) string {
	if v == nil {
		return ""
	}
	return fmt.Sprintf("%02d", *v)
}

// ---- item composition -------------------------------------------------------

// ItemName is an item's display name, precedence exactly (display-naming
// D-2): the item's stored title_override first, then the composed element
// name — its episode facts joined to the series its parsed anchor resolves
// to, rendered through the active element template — then the config-driven
// title walk over the item's OWN document namespaces (the same SourceTitle
// walk the series chain uses — plugin-title-enrichment), then the document's
// _view.title.value verbatim, then "". The walk leg is the floor for EVERY
// failed item composition, not just films: a film (no series row, no episode
// facts), a missing template, an unresolved series, or a tombstoned series
// all reach it before the _view floor. Every floor leg is honest — the
// composer never fabricates a name. Cyrillic passes through every leg
// verbatim, as everywhere in this package.
func (n Namer) ItemName(it store.Item, override string) string {
	if override != "" {
		return override
	}
	doc := DocMap(it.Document)
	if n.ElementTmpl != "" {
		if name, ok := n.ElementName(doc); ok {
			return name
		}
	}
	if title := n.SourceTitle(doc); title != "" {
		return title
	}
	return viewTitle(doc)
}

// ElementName resolves the composed element name from a parsed item document:
// the episode facts joined to the series row the parsed.series_relative_path
// anchor names. ok=false when any join leg is missing — no facts, no anchor,
// no matching row, or a row whose status is "deleted" (the SPA's matchSeries
// skips tombstones) — and the caller floors instead of fabricating. The
// {title} token is the resolved series' own name, through the same
// SeriesName chain under the library's group style. Shared by ItemName's
// composed tier and the api-side source_admin preview's no-data verdict.
func (n Namer) ElementName(doc map[string]any) (string, bool) {
	sr, season, episode, ok := n.ElementFacts(doc)
	if !ok {
		return "", false
	}
	return composeItemName(n.ElementTmpl, elementTokens{
		Title:   n.SeriesName(sr, n.SeriesOverride),
		Season:  &season,
		Episode: &episode,
	}), true
}

// ElementFacts resolves the join the composed element name renders against:
// the series row the item document's parsed anchor names plus the (season,
// episode) pair. ok=false when any leg is missing — no template, no facts, no
// matching row, or a row whose status is "deleted" (the SPA's matchSeries
// skips tombstones). Shared by elementName and the DTO seam's per-row series
// override point read, so both see exactly one join.
func (n Namer) ElementFacts(doc map[string]any) (sr store.Series, season, episode int64, ok bool) {
	if n.ElementTmpl == "" {
		return store.Series{}, 0, 0, false
	}
	path, s, e, fok := EpisodeFacts(doc)
	if !fok {
		return store.Series{}, 0, 0, false
	}
	sr, ok = n.SeriesByPath[path]
	if !ok || sr.Status == "deleted" {
		return store.Series{}, 0, 0, false
	}
	return sr, s, e, true
}

// EpisodeFacts reads the item document's episode identity — the series anchor
// parsed.series_relative_path plus the (season, episode) pair —
// namespace-agnostically: any sources.* namespace carrying BOTH integers
// qualifies (the SPA's numberField semantics: an integer-valued JSON number).
// The read order is FIXED — serial-parser, then tv-parser, then the remaining
// namespaces sorted — so Go map iteration order never leaks into a name
// (display-naming D-3). episode_end is not consumed in v1.
func EpisodeFacts(doc map[string]any) (path string, season, episode int64, ok bool) {
	parsed, _ := doc["parsed"].(map[string]any)
	path = strField(parsed, "series_relative_path")
	if path == "" {
		return "", 0, 0, false
	}
	sources, _ := doc["sources"].(map[string]any)
	for _, name := range factNamespaces(sources) {
		ns, ok := sources[name].(map[string]any)
		if !ok {
			continue
		}
		s, sok := intField(ns["season"])
		e, eok := intField(ns["episode"])
		if sok && eok {
			return path, s, e, true
		}
	}
	return "", 0, 0, false
}

// factNamespaces lists sources' namespace keys in the fixed fact-read order:
// the two verified writer namespaces first (serial-parser, then tv-parser —
// D-3), the rest sorted after them. A nil/empty sources map yields nil.
func factNamespaces(sources map[string]any) []string {
	if len(sources) == 0 {
		return nil
	}
	rest := make([]string, 0, len(sources))
	for name := range sources {
		if name != "serial-parser" && name != "tv-parser" {
			rest = append(rest, name)
		}
	}
	sort.Strings(rest)
	ordered := make([]string, 0, len(rest)+2)
	if _, ok := sources["serial-parser"]; ok {
		ordered = append(ordered, "serial-parser")
	}
	if _, ok := sources["tv-parser"]; ok {
		ordered = append(ordered, "tv-parser")
	}
	return append(ordered, rest...)
}

// viewTitle is the item document's own _view.title.value floor, verbatim: a
// string passes through as-is; a JSON number renders as its literal bytes
// (the JS String(value) lossless primitive stringify, INV-no-rounding);
// anything else — absent, null, object — floors to "" (the SPA renders its
// em-dash placeholder for the empty string).
func viewTitle(doc map[string]any) string {
	view, ok := doc["_view"].(map[string]any)
	if !ok {
		return ""
	}
	title, ok := view["title"].(map[string]any)
	if !ok {
		return ""
	}
	switch v := title["value"].(type) {
	case string:
		return v
	case json.Number:
		return v.String()
	default:
		return ""
	}
}

// intField reads a dynamic namespace field the way the SPA's numberField
// does: an integer-valued JSON number (JS Number.isInteger — "2.0" and "2e2"
// qualify, "2.5" and "2" as a string do not), else !ok.
func intField(v any) (int64, bool) {
	n, ok := v.(json.Number)
	if !ok {
		return 0, false
	}
	f, err := n.Float64()
	if err != nil || f != math.Trunc(f) {
		return 0, false
	}
	return int64(f), true
}
